import java.util.concurrent.*;

class Demo {

  public static void main(String[] args) throws Exception {
    var gate = new CountDownLatch(1);
    try (var p = new ThreadPoolExecutor(1, 1, 0, TimeUnit.SECONDS, new ArrayBlockingQueue<>(1))) {
      p.submit(
          () -> {
            gate.await();
            return 1;
          });
      p.submit(() -> 2);
      try {
        p.submit(() -> 3);
